output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "On entering the shop, the shopper is obliged to take the available cart from the entry cart rack before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_rack": "at(1,5)",
        "entry_cart_available": "cartAt(1,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_rack",
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entry_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        },
        "pickup_item_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "A shopper is prohibited from carrying groceries loose in their hands rather than in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_loose_goods": "handFull",
        "hands_free": {
          "not": "handFull"
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "and": [
              {
                "not": "handFull"
              },
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "carrying_loose_goods"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_loose_goods"
    }
  },
  {
    "id": "return_cart_to_front_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the front return bay at cell (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_rack": "at(1,5)",
        "at_front_return_bay": "at(0,1)",
        "entry_cart_available": "cartAt(1,5)",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_rack",
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "at_front_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_entry_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "cart_may_only_be_left_at_bay",
    "text": "A shopper is prohibited from putting a cart down anywhere except the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_front_return_bay": "at(0,1)",
        "outside_front_return_bay": {
          "not": "at(0,1)"
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "pushing_cart",
              "outside_front_return_bay"
            ]
          },
          "post": null
        },
        "leave_cart_at_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "pushing_cart",
              "at_front_return_bay"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_exit_before_cart_returned",
    "text": "The shopper is prohibited from exiting the supermarket unless their cart is already parked in the return bay and they are no longer holding it.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "not_pushing_cart": {
          "not": "hasCart"
        },
        "cart_safely_returned": {
          "and": [
            "cart_parked_in_return_bay",
            "not_pushing_cart"
          ]
        }
      },
      "events": {
        "exit_with_cart_not_returned": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "cart_safely_returned"
              }
            ]
          },
          "post": null
        },
        "exit_after_cart_return": {
          "pre": {
            "and": [
              "EXIT",
              "cart_safely_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart_not_returned"
    }
  },
  {
    "id": "no_carts_in_eastern_exit_zone",
    "text": "Carts are prohibited in the eastern exit zone, although shoppers may walk there after parking the cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        },
        "eastern_exit_zone": {
          "ge": [
            "x",
            7
          ]
        },
        "cart_in_eastern_exit_zone": {
          "and": [
            "pushing_cart",
            "eastern_exit_zone"
          ]
        }
      },
      "events": {
        "enter_eastern_exit_zone_with_cart": {
          "pre": {
            "and": [
              "MOVE",
              "pushing_cart"
            ]
          },
          "post": "eastern_exit_zone"
        },
        "walk_in_eastern_exit_zone_without_cart": {
          "pre": {
            "and": [
              "MOVE",
              "cartless"
            ]
          },
          "post": "eastern_exit_zone"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_eastern_exit_zone"
    }
  },
  {
    "id": "turn_back_from_right_shelf_with_cart",
    "text": "After interacting with the far-right shelf at (6,4) while pushing a cart, the shopper is obliged to turn back west rather than continue farther east.",
    "abstraction": {
      "state_properties": {
        "at_far_right_shelf": "at(6,4)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "far_right_shelf_pickup_with_cart": {
          "pre": {
            "and": [
              "at_far_right_shelf",
              "pushing_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "turn_west_at_far_right_shelf": {
          "pre": {
            "and": [
              "at_far_right_shelf",
              "pushing_cart",
              "W"
            ]
          },
          "post": null
        },
        "continue_east_from_far_right_shelf": {
          "pre": {
            "and": [
              "at_far_right_shelf",
              "pushing_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "far_right_shelf_pickup_with_cart",
      "discharge": "turn_west_at_far_right_shelf"
    }
  }
]
